/* ===== STÜDYO · YERLEŞİK LUT FİLTRELERİ (Karanlık Oda koduna dokunmadan) =====
   Sarı Sonbahar: yeşil orman fotoğrafı → altın sonbahar düzenlemesinden uydurulmuş 33³ 3B LUT.
   Filtreler › Lightroom tarzı'na eklenir. Veri sayfada gömülü; kitaplığa (IndexedDB) yazılmaz. */
(function(){
  if (!window.STUDYO || typeof LOOKS === 'undefined' || typeof DB === 'undefined') return;
  var YER = {
    'st-sari-sonbahar': {id:'st-sari-sonbahar', name:'Sarı Sonbahar', N:33, b64:''}
  };
  var FILTRE = [{id:'lr_sari_sonbahar', cat:'lr', n:'Sarı Sonbahar', p:{}, h:{}, lut:'st-sari-sonbahar'}];
  var hazir = {};
  function lut(id){ var y = YER[id]; if (!y) return null; if (hazir[id]) return hazir[id];
    var s = atob(y.b64), n = y.N*y.N*y.N, d = new Uint8Array(n*4);
    for (var i = 0, j = 0; i < n; i++){ d[j++] = s.charCodeAt(i*3); d[j++] = s.charCodeAt(i*3+1); d[j++] = s.charCodeAt(i*3+2); d[j++] = 255; }
    return hazir[id] = {id:y.id, name:y.name, N:y.N, data:d}; }
  var lutOf = {}; FILTRE.forEach(function(f){ if (!LOOKS.some(function(l){ return l.id === f.id; })){ LOOKS.push({id:f.id, cat:f.cat, n:f.n, p:f.p, h:f.h}); } lutOf[f.id] = f.lut; });
  /* görünüm çözümlemesi: yerleşik filtreye LUT bağla (doğrudan seçilmiş ya da hazır ayarın içindeki filtre) */
  var eskiRL = window.resolveLook;
  window.resolveLook = function(look){ var r = eskiRL.apply(this, arguments); if (!r || !look) return r;
    var id = String(look.id || '');
    if (lutOf[id]) r.lut = {id: lutOf[id], amt: 100};
    else if (id.indexOf('u:') === 0 && !r.lut && typeof Presets !== 'undefined'){ var pr = Presets.byId(id.slice(2));
      if (pr && pr.look && lutOf[pr.look.id]) r.lut = {id: lutOf[pr.look.id], amt: pr.look.amt || 100}; }
    return r; };
  /* LUT verisi: önce yerleşik, yoksa kitaplık */
  var eskiGet = DB.lutGet;
  DB.lutGet = function(id){ var y = lut(id); return y ? Promise.resolve(y) : eskiGet.apply(DB, arguments); };
  /* önizleme ve küçük resimler: yerleşik LUT eşzamanlı yüklenir (ilk küçük resim LUT'suz çizilip önbelleğe girmesin) */
  var eskiPrep = window.prepPipe;
  window.prepPipe = function(eff){ try { var w = eff && !eff.style && eff.lut3 && eff.lut3.id, y = w && lut(w);
      if (y && typeof ED !== 'undefined' && ED.pipe && ED.lut3Id !== w){ ED.pipe.setLut3(y.data, y.N); ED.lut3Id = w; ED.lut3Loading = null; } } catch(e){ console.warn('Stüdyo LUT', e); }
    return eskiPrep.apply(this, arguments); };
})();
